import { cn } from "@/lib/utils"

export function SectionHeading({
  eyebrow,
  title,
  description,
  className,
}: {
  eyebrow?: string
  title: React.ReactNode
  description?: React.ReactNode
  className?: string
}) {
  return (
    <div
      className={cn(
        "mx-auto flex max-w-2xl flex-col items-center gap-4 text-center",
        className
      )}
    >
      {eyebrow && (
        <span className="rounded-full border border-primary/60 px-3 py-1 text-sm font-medium text-primary">
          {eyebrow}
        </span>
      )}
      <h2 className="text-3xl font-normal tracking-tight text-balance sm:text-4xl md:text-5xl">
        {title}
      </h2>
      {description && (
        <p className="text-base text-pretty text-muted-foreground sm:text-lg">
          {description}
        </p>
      )}
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Product screenshot inside an animated gradient border.
 * Falls back to a skeleton dashboard when `src` is missing or fails to load,
 * so the block still looks right before you add your own screenshots.
 */
export function ScreenFrame({
  src,
  alt,
  width = 1512,
  height = 982,
  priority = false,
  tilt = true,
  className,
}: {
  src?: string
  alt: string
  width?: number
  height?: number
  priority?: boolean
  tilt?: boolean
  className?: string
}) {
  const [failed, setFailed] = React.useState(false)

  return (
    <div
      className={cn(
        "relative rounded-[1.75rem] bg-linear-45 from-primary/70 via-background to-primary/70 bg-[length:300%_300%] p-0.5 shadow-[0_0_96px_color-mix(in_oklab,var(--primary)_16%,transparent)] transition-[transform,box-shadow] duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] animate-geneva-gradient motion-reduce:animate-none",
        tilt &&
          "hover:shadow-[0_0_128px_color-mix(in_oklab,var(--primary)_32%,transparent)] hover:[transform:perspective(900px)_rotateX(3deg)_rotateY(2deg)] motion-reduce:hover:transform-none",
        className
      )}
    >
      <div className="overflow-hidden rounded-[1.625rem] border-4 border-background bg-card sm:border-8">
        {src && !failed ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={src}
            alt={alt}
            width={width}
            height={height}
            loading={priority ? "eager" : "lazy"}
            fetchPriority={priority ? "high" : "auto"}
            onError={() => setFailed(true)}
            className="block h-auto w-full"
          />
        ) : (
          <ScreenPlaceholder label={alt} ratio={width / height} />
        )}
      </div>
    </div>
  )
}

function ScreenPlaceholder({ label, ratio }: { label: string; ratio: number }) {
  return (
    <div
      role="img"
      aria-label={label}
      style={{ aspectRatio: ratio }}
      className="grid w-full grid-cols-[18%_1fr] gap-3 bg-card p-3 sm:gap-4 sm:p-5"
    >
      <div className="flex flex-col gap-2 rounded-xl bg-muted/60 p-3">
        <div className="mb-2 h-3 w-2/3 rounded-full bg-primary/40" />
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="h-2.5 w-full rounded-full bg-muted" />
        ))}
      </div>
      <div className="grid grid-rows-[auto_1fr_1fr] gap-3 sm:gap-4">
        <div className="h-4 w-1/3 rounded-full bg-muted" />
        <div className="grid grid-cols-3 gap-3 sm:gap-4">
          <div className="rounded-xl bg-muted/60" />
          <div className="col-span-2 flex items-end gap-1.5 rounded-xl bg-muted/60 p-3">
            {[40, 70, 55, 85, 45, 75, 60, 90, 50].map((h, i) => (
              <div
                key={i}
                style={{ height: `${h}%` }}
                className="flex-1 rounded-sm bg-primary/50"
              />
            ))}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-3 sm:gap-4">
          <div className="rounded-xl bg-muted/60" />
          <div className="rounded-xl bg-muted/60" />
        </div>
      </div>
    </div>
  )
}

import { CheckIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { ScreenFrame } from "@/components/geneva/screen-frame"
import { SectionHeading } from "@/components/geneva/section-heading"

const features = [
  {
    title: "Analytics that explain themselves",
    description:
      "Income, spending and savings broken down by week, month or year. Geneva highlights what changed and why, so you never have to dig through spreadsheets again.",
    points: ["Cash-flow forecasts", "Category trends", "Exportable reports"],
    image: "/geneva/analytics.jpg",
  },
  {
    title: "Virtual and physical cards",
    description:
      "Issue cards in seconds, set spending limits per card and freeze them with one tap. Perfect for subscriptions, travel or your whole team.",
    points: ["Instant virtual cards", "Per-card limits", "One-tap freeze"],
    image: "/geneva/my-cards.jpg",
  },
  {
    title: "An assistant that knows your money",
    description:
      "Ask questions in plain language — “How much did I spend on travel this year?” — and get answers, charts and suggestions instantly.",
    points: ["Natural-language search", "Smart suggestions", "Private by design"],
    image: "/geneva/ai-chat-1.jpg",
  },
]

export function Features({ className }: { className?: string }) {
  return (
    <section
      id="features"
      className={cn("scroll-mt-20 border-t border-border py-20", className)}
    >
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <SectionHeading title="Features" />
        <div className="mt-16 flex flex-col gap-20 lg:gap-28">
          {features.map((feature, index) => (
            <div
              key={feature.title}
              className="grid items-center gap-10 lg:grid-cols-2 lg:gap-20"
            >
              <div className={cn("flex flex-col gap-4", index % 2 === 1 && "lg:order-last")}>
                <h3 className="text-2xl font-medium sm:text-3xl">
                  {feature.title}
                </h3>
                <p className="text-muted-foreground sm:text-lg">
                  {feature.description}
                </p>
                <ul className="mt-2 flex flex-col gap-3">
                  {feature.points.map((point) => (
                    <li key={point} className="flex items-center gap-3">
                      <CheckIcon className="size-5 text-primary" />
                      {point}
                    </li>
                  ))}
                </ul>
              </div>
              <ScreenFrame src={feature.image} alt={feature.title} />
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}
